REAL = {"small": "claude-haiku-4-5", "mid": "claude-sonnet-5", "reasoning": "claude-opus-5"}


class RealProvider:
    def __init__(self):
        import anthropic
        self.client = anthropic.Anthropic()        # reads ANTHROPIC_API_KEY

    def complete(self, tier, task):
        t0 = time.time()
        r = self.client.messages.create(
            model=REAL[tier], max_tokens=256,
            # per task type, and the last line is what graded() parses
            system="Do the task. Your LAST line must be: ANSWER: <one of %s>"
                   % ", ".join(LABELS[task["type"]]),
            messages=[{"role": "user", "content": task["prompt"][:4000]}],
        )
        text = "".join(b.text for b in r.content if b.type == "text")
        return {"text": text, "in_tok": r.usage.input_tokens,   # real usage, not an estimate
                "out_tok": r.usage.output_tokens,
                "latency_ms": round((time.time() - t0) * 1000, 1)}

# REPLACE the whole __main__ block
FLOOR = {"pass": 0.90, "hard": 0.90}    # the ratchet CI enforces on every prompt change


def gate(prod, cand, n):
    bad = []
    if cand["pass"] < FLOOR["pass"] * n:
        bad.append("pass %d/%d under floor" % (cand["pass"], n))
    if cand["hard_ok"] < FLOOR["hard"] * cand["hard"]:
        bad.append("hard %d/%d under floor" % (cand["hard_ok"], cand["hard"]))
    if cand["pass"] < prod["pass"]:
        bad.append("regressed vs prod %d" % prod["pass"])
    print("\nGATE %s   [%+d pass, %+d chars/call vs prod]"
          % ("PASS" if not bad else "FAIL: " + "; ".join(bad),
             cand["pass"] - prod["pass"], cand["chars"] - prod["chars"]))
    return 1 if bad else 0


if __name__ == "__main__":
    cases, model, t = make_cases(), MockModel(), {}
    for v in sorted(PROMPTS):
        t[v] = report(PROMPTS[v], cases, model)
    raise SystemExit(gate(t[5], t[max(PROMPTS)], len(cases)))    # 5 = what is deployed

# above __main__
def table(results):
    print("model         lb  score   $/suite   p95 ms   $ per correct")
    for r in results:
        print("  %-11s %3d  %3.0f%%   %7.4f   %6.0f   %.5f" % (
            r["model"], CATALOG[r["model"]]["lb"], 100.0 * r["ok"] / r["n"],
            r["usd"], r["p95_ms"], r["usd"] / max(r["ok"], 1)))

# REPLACE __main__ entirely
if __name__ == "__main__":
    cases, gw = golden_set(), MockGateway()
    results = [run(m, cases, gw) for m in CATALOG]   # every candidate, same 50 cases
    table(results)
    with open("bench.jsonl", "w", encoding="utf-8") as fh:
        for r in results:
            for rec in r["recs"]:
                fh.write(json.dumps(rec) + "\n")

# above table()
def decide(agg, route):
    """The swap rule, agreed BEFORE the release: a launch becomes a diff."""
    inc = agg[(route, INCUMBENT)]
    inc_score, inc_usd = 100.0 * inc["ok"] / inc["n"], inc["usd"]
    for m in sorted(CATALOG, key=lambda k: agg[(route, k)]["usd"]):   # cheapest first
        a = agg[(route, m)]
        score = 100.0 * a["ok"] / a["n"]
        if m == INCUMBENT:
            continue
        if score >= inc_score - 2 and a["usd"] <= 0.5 * inc_usd:
            return m, "same quality, %.0fx cheaper" % (inc_usd / a["usd"])
        if score >= inc_score + 10:
            return m, "+%.0f pts, worth paying for" % (score - inc_score)
    return INCUMBENT, "no candidate cleared the bar"


def plan(agg):
    cfg = {}
    for route in CASES:
        pick, why = decide(agg, route)
        cfg[route] = pick
        print("  %s %-13s -> %-11s  (%s)" %
              ("KEEP" if pick == INCUMBENT else "SWAP", route, pick, why))
    with open("routes.json", "w", encoding="utf-8") as fh:
        json.dump(cfg, fh, indent=2)

# end of __main__
    plan(agg)

# above decide()
def confidence(path):
    """Would another 50 cases say the same? Resample YOURS 2000x, watch the delta."""
    ok, ids = {}, {}
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            r = json.loads(line)
            ok[(r["route"], r["model"], r["id"])] = r["ok"]
            if r["model"] == INCUMBENT:
                ids.setdefault(r["route"], []).append(r["id"])
    print("  route         vs incumbent  delta  90% interval   verdict")
    for route in CASES:
        for m in [k for k in CATALOG if k != INCUMBENT]:
            d = [ok[(route, m, i)] - ok[(route, INCUMBENT, i)] for i in ids[route]]
            rng = random.Random("boot|%s|%s" % (route, m))
            b = sorted(sum(rng.choice(d) for _ in d) / len(d) for _ in range(2000))
            lo, hi, mean = b[100], b[1899], sum(d) / len(d)
            need = int((1.645 * statistics.pstdev(d) / mean) ** 2) + 1 if mean else 0
            print("  %-13s %-12s %+5.0f  [%+4.0f,%+4.0f]   %s" % (
                route, m, 100 * mean, 100 * lo, 100 * hi, "resolved" if lo > 0 or hi < 0
                else "unresolved, need ~%d cases" % need if need else "dead tie"))

# end of __main__
    confidence("bench.jsonl")

