REAL = {"mock-mini-2": "claude-haiku-4-5", "mock-pro-4": "claude-sonnet-5",
        "mock-max-9": "claude-opus-5"}


class RealGateway:
    """Same .call() -> same dict. Nothing downstream can tell."""

    def __init__(self):
        import anthropic
        self.client = anthropic.Anthropic()        # reads ANTHROPIC_API_KEY

    def call(self, model, case):
        t0 = time.time()
        r = self.client.messages.create(
            model=REAL[model], max_tokens=1024,    # room for thinking AND the answer
            system="Reply with one final line: ANSWER: <label>, one of: "
                   + ", ".join(LABELS[case["route"]]),
            messages=[{"role": "user", "content": case["input"][:4000]}],
        )
        text = "".join(b.text for b in r.content if b.type == "text")
        return {"text": text, "in_tok": r.usage.input_tokens,   # real usage, not a guess
                "out_tok": r.usage.output_tokens,
                "latency_ms": round((time.time() - t0) * 1000, 1)}

# paste directly above rank_of()
DOCS = [(c[0], tokens(c[3])) for c in CORPUS]
DF = {}
for _, _ts in DOCS:
    for _w in set(_ts):
        DF[_w] = DF.get(_w, 0) + 1
AVGLEN = sum(len(t) for _, t in DOCS) / len(DOCS)
N = len(DOCS)


def bm25_search(query, k1=1.5, b=0.75):
    """Lexical scoring. Rare tokens - an acronym, a part number - weigh most."""
    scored = []
    for cid, ts in DOCS:
        s = 0.0
        for w in tokens(query):
            if w not in DF:
                continue                     # not in the corpus at all: no signal
            tf = ts.count(w)
            idf = math.log(1 + (N - DF[w] + 0.5) / (DF[w] + 0.5))
            s += idf * tf * (k1 + 1) / (tf + k1 * (1 - b + b * len(ts) / AVGLEN))
        scored.append((s, cid))
    return [cid for s, cid in sorted(scored, key=lambda p: (-p[0], p[1])) if s > 0]

# __main__: add the column
    report({"dense": dense_search, "bm25": bm25_search})

# below bm25_search()
def rrf_search(query, k=60):
    """Reciprocal rank fusion. Only positions are combined, never scores - which is
    why it needs no normalization between two differently-scaled retrievers."""
    fused = {}
    for search in (dense_search, bm25_search):
        for rank, cid in enumerate(search(query)):
            fused[cid] = fused.get(cid, 0.0) + 1.0 / (k + rank + 1)
    return [cid for cid, _ in sorted(fused.items(), key=lambda x: (-x[1], x[0]))]


def sweep(searchers):
    print("== recall@k: what a bigger context budget buys ==")
    print("  %-10s%s" % ("k", "".join("%8s" % n for n in searchers)))
    ranks = dict((n, [rank_of(searchers[n](q), g) for q, g in GOLD]) for n in searchers)
    for k in (1, 2, 3, 5, 10):
        print("  %-10d%s" % (k, "".join("%8s" % ("%d/%d" % (
            sum(1 for r in ranks[n] if r and r <= k), len(GOLD))) for n in searchers)))

# REPLACE __main__
if __name__ == "__main__":
    S = {"dense": dense_search, "bm25": bm25_search, "hybrid": rrf_search}
    report(S)
    print()
    sweep(S)

