"""Minimal agent - plan, act, observe - LAB STARTER (deliberately naive).
Task: total the USD owed across the invoices in ./inbox, then report it. Stdlib
only, no keys: real files, real tools, a mocked model. The loop has no bounds, no
trace, no verification - that is the lab. PIN/POUT are EXAMPLE Aug-2026 magnitudes."""
import random, re
from collections import Counter
from pathlib import Path

INBOX, OUTBOX = Path("inbox"), Path("outbox.log")
DOCS = {"acme.txt":    "Invoice ACME-8812\nAmount due: 1240.50 USD\n",
        "globex.txt":  "Invoice GLBX-4417\nAmount due: 880.00 USD\n",
        "initech.txt": "Invoice INI-9003\nAmount due: 2115.25 USD\n",
        "readme.txt":  "Q3 close is Friday. No invoice on this page.\n"}
TRUTH = 4235.75                # 1240.50 + 880.00 + 2115.25
FLAKY = {"initech.txt": 0.45}  # one file is on cold storage. the agent does not know
PIN, POUT = 3.0, 15.0          # $ per 1M tokens, illustrative
AMT = re.compile(r"Amount due: ([\d.]+) USD")

def setup():
    INBOX.mkdir(exist_ok=True)
    for name, body in DOCS.items():
        (INBOX / name).write_text(body, encoding="utf-8")
    OUTBOX.write_text("", encoding="utf-8")

def p95(xs):  # nearest rank: ceil(.95n)-1. the usual xs[int(n*.95)] is the max, not p95
    return xs[(len(xs) * 95 + 99) // 100 - 1]

# tools: narrow scope, one job each, errors that say what to do next
def t_list_files(_arg, rng):
    return " ".join(sorted(p.name for p in INBOX.iterdir()))

def t_read_file(name, rng):
    path = INBOX / Path(name).name  # least privilege: no escaping the inbox
    if not path.is_file():
        return "ERROR: no file %r - call list_files first" % name
    if rng.random() < FLAKY.get(path.name, 0.08):
        return "ERROR: storage busy - retry the same path"
    return path.read_text(encoding="utf-8").strip()

def t_calc(expr, rng):  # arithmetic only: no eval(), no builtins, no names
    try:
        return "%.2f" % sum(float(x) for x in expr.split("+"))
    except ValueError:
        return "ERROR: calc adds numbers separated by + , got %r" % expr

def t_send_report(amount, rng):
    with OUTBOX.open("a", encoding="utf-8") as fh:  # IRREVERSIBLE: it leaves the process
        fh.write("to finance@corp: invoices total %s USD\n" % amount)
    return "sent"

TOOLS = {"list_files": t_list_files, "read_file": t_read_file,
         "calc": t_calc, "send_report": t_send_report}

class MockModel:
    """Reads the observation history, emits ONE action, slips `err` of the time."""
    def __init__(self, err=0.25):
        self.err = err

    def act(self, hist, rng):
        obs = {(a, g): o for a, g, o in hist}
        names = [n for (a, g), o in obs.items() if a == "list_files" for n in o.split()]
        read = {g: o for (a, g), o in obs.items() if a == "read_file" and "ERROR" not in o}
        amts = sorted(m.group(1) for o in read.values() for m in [AMT.search(o)] if m)
        expr = " + ".join(amts)
        done = [o for (a, g), o in obs.items() if a == "calc" and g == expr and "ERROR" not in o]
        todo = sorted(set(names) - set(read))
        if not names:            act = ("list_files", "")
        elif todo:               act = ("read_file", todo[0])
        elif amts and not done:  act = ("calc", expr)
        else:                    act = ("send_report", done[-1] if done else "0.00")
        if names and rng.random() < self.err:  # the slip. this is what compounds
            if act[0] == "read_file" and rng.random() < 0.5:
                act = ("read_file", act[1].replace(".txt", ".pdf"))  # guessed path
            elif act[0] == "read_file":
                act = ("calc", expr or "0")  # stops reading early
            elif act[0] == "calc":
                act = ("send_report", "%.2f" % sum(float(x) for x in amts[:-1]))  # mental math
            else:
                act = ("send_report", "4000.00")  # premature victory
        return act

def run(seed, model):
    rng = random.Random(seed)
    hist, steps, in_tok, out_tok = [], 0, 0, 0

    def stop(why, answer="0.00"):
        return {"stop": why, "answer": answer, "steps": steps, "hist": hist,
                "usd": in_tok * PIN / 1e6 + out_tok * POUT / 1e6}

    while True:  # STARTER: nothing bounds this loop
        act, arg = model.act(hist, rng)
        steps += 1
        in_tok += 400 + 60 * len(hist)  # the whole history is re-sent every turn
        out_tok += 30
        hist.append((act, arg, TOOLS[act](arg, rng)))
        if act == "send_report":  # the model says done, so the loop says done
            return stop("reported", arg)

def report(label, runs):
    n = len(runs)
    st = sorted(r["steps"] for r in runs)
    usd = sorted(r["usd"] for r in runs)
    ok = sum(abs(float(r["answer"]) - TRUTH) < 0.01 for r in runs)
    claimed = sum(r["stop"] == "reported" for r in runs)
    sent = OUTBOX.read_text(encoding="utf-8").splitlines()
    print("== %s ==" % label)
    print("  stops    %s" % dict(sorted(Counter(r["stop"] for r in runs).items())))
    print("  claimed  %d/%d done   correct %d/%d (%.0f%%)" % (claimed, n, ok, n, 100.0 * ok / n))
    print("  steps    mean %.1f  p95 %d  max %d    cost $%.4f  p95 $%.4f  max $%.4f"
          % (sum(st) / n, p95(st), st[-1], sum(usd), p95(usd), usd[-1]))
    print("  outbox   %d emails to finance, %d wrong"
          % (len(sent), sum(1 for x in sent if ("%.2f" % TRUTH) not in x)))

def batch(label, n=200, **kw):
    setup()
    runs = [run("run|%d" % i, MockModel(), **kw) for i in range(n)]
    demo = sorted(runs, key=lambda r: r["steps"])[n // 2]
    print("-- trace of a median run (%d steps) --" % demo["steps"])
    for i, (a, g, o) in enumerate(demo["hist"], 1):
        print("  %2d %-11s %-22s -> %s" % (i, a, g[:22], o.replace("\n", " ")[:38]))
    report(label, runs)
    return runs

if __name__ == "__main__":
    batch("no bounds, no gate")

