"""LLM gateway with mocked providers - LAB STARTER (deliberately naive).
Stdlib only. Config lives in dicts; in production it is the gateway's YAML.
Prices are EXAMPLE Aug-2026 magnitudes (USD per 1M tokens).
"""
import json, math, random

PROVIDERS = {  # two DIFFERENT companies - tier -> (model id, $/MTok in, $/MTok out)
    "acme":   {"mid": ("acme-m3", 2.0, 10.0), "big": ("acme-l3", 5.0, 25.0), "ms": 400},
    "globex": {"mid": ("gx-flash", 3.0, 15.0), "big": ("gx-pro", 9.0, 36.0), "ms": 520},
}
ROUTES = {  # routes name a capability TIER and a pool - never a vendor in app code
    "support-chat": {"tier": "mid", "pool": ["acme"], "share": 0.60},
    "doc-summary":  {"tier": "mid", "pool": ["acme"], "share": 0.25},
    "code-review":  {"tier": "big", "pool": ["acme"], "share": 0.15},
}
SHAPE = {"support-chat": (900, 220), "doc-summary": (7000, 400), "code-review": (4000, 900)}
OUTAGES = {"acme": [(180, 420)]}  # scripted incident: acme 503s from t=180s to t=420s
TIMEOUT_MS = 900  # what ONE failing upstream call costs you in wall clock
N_REQ = 600       # one request per second, for ten minutes


class ProviderDown(Exception):
    pass


class MockProvider:
    """Returns the shape an SDK returns, or raises during a scripted outage."""

    def __init__(self, name):
        self.name, self.calls = name, 0

    def complete(self, tier, req):
        self.calls += 1
        for lo, hi in OUTAGES.get(self.name, []):
            if lo <= req["t"] < hi:
                raise ProviderDown("%s 503 at t=%ds" % (self.name, req["t"]))
        model, pin, pout = PROVIDERS[self.name][tier]
        rng = random.Random("out|" + req["id"])  # length is a property of the task
        out_tok = int(req["out_tok"] * rng.uniform(0.8, 1.2))
        return {"model": model, "in_tok": req["in_tok"], "out_tok": out_tok,
                "ms": round(PROVIDERS[self.name]["ms"] + out_tok * 1.1, 1),
                "usd": (req["in_tok"] * pin + out_tok * pout) / 1e6}


# THE ONE PLACE A REAL API PLUGS IN: a provider is anything with a
# .complete(tier, req) returning that dict. Step 7 builds one.


def make_traffic(n=N_REQ):
    rng, reqs = random.Random(7), []
    names, weights = list(ROUTES), [ROUTES[r]["share"] for r in ROUTES]
    for i in range(n):
        route = rng.choices(names, weights)[0]
        reqs.append({"id": "r%04d" % i, "route": route, "t": i,  # t = second
                     "in_tok": SHAPE[route][0], "out_tok": SHAPE[route][1]})
    return reqs


class Gateway:
    """Single choke point for all model traffic. STARTER: it only forwards."""

    def __init__(self):
        self.providers = {n: MockProvider(n) for n in PROVIDERS}

    def send(self, req):
        cfg = ROUTES[req["route"]]
        name = cfg["pool"][0]
        r = self.providers[name].complete(cfg["tier"], req)
        r.update({"provider": name, "attempts": 1, "ok": True})
        return r


def run(gw, reqs):
    recs = []
    for req in reqs:
        try:
            r = gw.send(req)
        except ProviderDown:
            r = {"provider": None, "attempts": 1, "ok": False,
                 "usd": 0.0, "ms": float(TIMEOUT_MS)}
        r.update({"id": req["id"], "route": req["route"], "t": req["t"]})
        recs.append(r)
    return recs


def p95(vals):
    """Nearest rank: ceil(0.95*n) - 1. The common `vals[int(n * 0.95)]` is
    off by one; on n=20 it hands you the max and calls it p95."""
    return vals[max(0, math.ceil(len(vals) * 95 / 100) - 1)] if vals else 0.0


def report(name, recs, gw):
    n, bad = len(recs), sum(not r["ok"] for r in recs)
    lat = sorted(r["ms"] for r in recs)
    print("== %s ==\n  requests %d   FAILED %d (%.1f%%)   spend $%.4f\n"
          "  p95 %.0f ms   upstream calls %s" %
          (name, n, bad, 100.0 * bad / n, sum(r["usd"] for r in recs),
           p95(lat), {k: p.calls for k, p in gw.providers.items()}))


if __name__ == "__main__":
    gw = Gateway()
    report("naive gateway: primary only", run(gw, make_traffic()), gw)

