"""docs-index MCP server + the harness that drives it - LAB STARTER (naive on purpose).
Stdlib only: no keys, no installs, no network, no SDK. Run it plain and it launches
`py -3 mcp_lab.py --server`, speaks newline-delimited JSON-RPC over that subprocess's
stdin/stdout, and keeps its stderr in server.log. The server is written to the 2025-11-25
era: it demands the initialize handshake. That is the bug.
"""
import json, subprocess, sys

COLLECTIONS = {"platform": ["rotate the signing key with vault-cli",
                            "failover runbook for the index replicas",
                            "signing key rotation is quarterly"],
               "public": ["support hours are 9-5 UTC", "getting started guide"]}
SESSION = [("signing key", "platform"), ("support hours", "public"), ("failover", "platform")]
TOOLS = [{"name": "search_docs",
          "description":
              "Search the engineering docs index; returns ranked, citable passages."
              "\nUSE WHEN asked about internal APIs, runbooks or architecture decisions."
              "\nDO NOT USE for source code (search_code) or tickets (search_issues)."
              "\nExample: search_docs(query=\"how do we rotate the signing key\").",
          "inputSchema": {"type": "object", "required": ["query"],
                          "properties": {"query": {"type": "string"},
                                         "collection": {"type": "string"}}}}]


def search_docs(args):
    coll = args.get("collection", "public")
    if coll not in COLLECTIONS: raise ValueError("unknown collection %r" % coll)
    hits = [t for t in COLLECTIONS[coll] if any(w in t for w in args["query"].split())]
    return {"passages": [{"doc_id": "%s-%d" % (coll, i), "text": t} for i, t in enumerate(hits)]}


def handle(method, params):
    if method == "initialize":                   # the handshake
        return {"protocolVersion": "2025-11-25", "serverInfo": {"name": "docs-index"},
                "capabilities": {"tools": {}}}
    if method == "tools/list":
        return {"tools": TOOLS}
    if method == "tools/call":
        return search_docs(params.get("arguments") or {})
    raise LookupError(method)


def serve():
    for line in sys.stdin:
        if not line.strip(): continue
        req = json.loads(line)
        out = {"jsonrpc": "2.0", "id": req["id"]}
        try:
            out["result"] = handle(req["method"], req.get("params") or {})
        except LookupError as e:
            out["error"] = {"code": -32601, "message": "method not found: %s" % e}
        except Exception as e:
            out["error"] = {"code": -32603, "message": str(e)}
        sys.stdout.write(json.dumps(out) + "\n")
        sys.stdout.flush()               # a pipe: nothing ships until you flush


class Client:      # exactly what a real client does
    def __init__(self):
        self.log = open("server.log", "w", encoding="utf-8")   # closed in close()
        self.proc = subprocess.Popen([sys.executable, __file__, "--server"],
                                     stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                     stderr=self.log,
                                     text=True, encoding="utf-8", bufsize=1)
        self.next_id, self.reqs, self.bytes = 0, 0, 0

    def call(self, method, params=None):
        self.next_id += 1              # every request gets a fresh JSON-RPC id
        req = {"jsonrpc": "2.0", "id": self.next_id, "method": method, "params": params or {}}
        self.proc.stdin.write(json.dumps(req) + "\n")
        self.proc.stdin.flush()
        line = self.proc.stdout.readline()
        self.reqs, self.bytes = self.reqs + 1, self.bytes + len(line)
        res = json.loads(line)
        return res["result"] if "result" in res else {"_error": res["error"]}

    def close(self):
        self.proc.stdin.close()
        self.proc.wait()
        self.log.close()           # the child is gone: release the handle


def main():
    c = Client()
    print("initialize   -> %s" % json.dumps(c.call("initialize")))
    for query, coll in SESSION:
        tools = c.call("tools/list")["tools"]    # refetched every turn: no cache directive
        r = c.call("tools/call", {"name": "search_docs",
                                  "arguments": {"query": query, "collection": coll}})
        print("turn %-14s hits=%d  tools=%s" % (query, len(r["passages"]),
                                                [t["name"] for t in tools]))
    print("session      -> %d requests, %d bytes read from the server" % (c.reqs, c.bytes))
    c.close()
    print("--- server.log (stderr) ---")
    with open("server.log", encoding="utf-8") as fh:
        sys.stdout.write(fh.read())


if __name__ == "__main__":
    if "--server" in sys.argv:
        print("docs-index ready", file=sys.stderr)   # stderr is free, stdout is the wire
        serve()
    else:
        main()

