import base64, hashlib, hmac, os, time   # add to the top imports

STATE_KEY = os.environ.get("MCP_STATE_KEY", "dev-key-vault-this-in-prod").encode()
TTL_S, SPENT = 300, set()   # in production SPENT is Redis, TTL_S as its expiry

def sign(raw): return hmac.new(STATE_KEY, raw, hashlib.sha256).digest()   # 32 bytes, fixed

def mint(sub, dig):
    raw = json.dumps({"sub": sub, "dig": dig, "exp": int(time.time()) + TTL_S},
                     sort_keys=True, separators=(",", ":")).encode()
    return base64.urlsafe_b64encode(raw + sign(raw)).decode()

def redeem(token, sub, dig):
    blob = base64.urlsafe_b64decode(token.encode())
    raw, sig = blob[:-32], blob[-32:]      # split on WIDTH; a digest holds any byte value
    if not hmac.compare_digest(sig, sign(raw)): raise ValueError("state failed its check")
    body = json.loads(raw)
    if body["sub"] != sub: raise ValueError("state belongs to another principal")
    if body["dig"] != dig: raise ValueError("state does not match this request")
